        IList<object> accountparamsAccountVariable = (IList<object>)this.handleOptionStringAndParams(parameters, "watchBalance", "account");
        string? account = (string)accountparamsAccountVariable[0];
        IDictionary<string, object> paramsAccount = ((IDictionary<string, object>)accountparamsAccountVariable[1]);
        if ((account != null))
        {
            if (!(account == "futures") && !(account == "flex_futures"))
            {
                throw new ArgumentsRequired ((this.id + " watchBalance account must be either 'futures' or 'flex_futures'")) ;
            }
            messageHash = messageHash + (":" + account);
        }
        return ccxt.BaseExchange.ToBalances(await this.subscribePrivate(name, messageHash, paramsAccount));
    }

    public virtual void handleTrade(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // snapshot
        //
        //    {
        //        "feed": "trade_snapshot",
        //        "product_id": "PI_XBTUSD",
        //        "trades": [
        //            {
        //                "feed": "trade",
        //                "product_id": "PI_XBTUSD",
        //                "uid": "caa9c653-420b-4c24-a9f2-462a054d86f1",
        //                "side": "sell",
        //                "type": "fill",
        //                "seq": 655508,
        //                "time": 1612269657781,
        //                "qty": 440,
        //                "price": 34893
        //            },
        //            ...
        //        ]
        //    }
        //
        // update
        //
        //    {
        //        "feed": "trade",
        //        "product_id": "PI_XBTUSD",
        //        "uid": "05af78ac-a774-478c-a50c-8b9c234e071e",
        //        "side": "sell",
        //        "type": "fill",
        //        "seq": 653355,
        //        "time": 1612266317519,
        //        "qty": 15000,
        //        "price": 34969.5
        //    }
        //
        string? channel = this.safeString(message, "feed");
        string? marketId = this.safeString(message, "product_id");
        if ((marketId != null))
        {
            Dictionary<string, object> market = this.market(marketId);
            string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
            string? messageHash = this.getMessageHash("trade", null, symbol);
            if ((this.safeList(this.trades, symbol) == null))
            {
                Int64? tradesLimit = this.safeInteger(this.options, "tradesLimit", 1000);
                this.trades[(string)symbol] = new ArrayCache(tradesLimit);
            }
            ccxt.pro.ArrayCache tradesArray = ((ccxt.pro.ArrayCache)(this.trades != null && symbol != null && this.trades.ContainsKey(symbol) ? this.trades[symbol] : null));
            if (channel == "trade_snapshot")
            {
                List<object> trades = this.safeList(message, "trades", new List<object>() {});
                int length = trades.Count;
                for (object i = 0; isLessThan(i, length); postFixIncrement(ref i))
                {
                    object index = subtract((length - 1), i); // need reverse to correct chronology
                    object item = getValue(trades, index);
                    Dictionary<string, object> trade = this.parseWsTrade(item);
                    tradesArray.append(trade);
                }
            } else
            {
                Dictionary<string, object> trade = this.parseWsTrade(message);
                tradesArray.append(trade);
            }
            client.resolve(tradesArray, messageHash);
        }
    }

    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        //    {
        //        "feed": "trade",
        //        "product_id": "PI_XBTUSD",
        //        "uid": "caa9c653-420b-4c24-a9f1-462a054d86f1",
        //        "side": "sell",
        //        "type": "fill",
        //        "seq": 655508,
        //        "time": 1612269657781,
        //        "qty": 440,
        //        "price": 34893
        //    }
        //
        // order update
        //     {
        //         "instrument": "PF_DOGEUSD",
        //         "time": 1778610421471,
        //         "last_update_time": 1778610444402,
        //         "qty": 0,
        //         "filled": 10,
        //         "limit_price": 0.10912,
        //         "stop_price": 0,
        //         "type": "limit",
        //         "order_id": "a1c3803c-8f3d-4317-a085-8d06e11b1d36",
        //         "direction": 0,
        //         "reduce_only": false
        //     }
        //
        string? marketId = this.safeString(trade, "product_id");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(trade, "time");
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", this.safeString(trade, "uid") },
            { "symbol", this.safeString(marketResolved, "symbol") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "order", null },
            { "type", this.safeString(trade, "type") },
            { "side", this.safeString(trade, "side") },
            { "takerOrMaker", "taker" },
            { "price", this.safeString2(trade, "price", "limit_price") },
            { "amount", this.safeString2(trade, "filled", "qty") },
            { "cost", null },
            { "fee", new Dictionary<string, object>() {
                { "rate", null },
                { "cost", null },
                { "currency", null },
            } },
        }, marketResolved);
    }

