    public virtual object handleOrder(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //  update (verbose)
        //
        //    {
        //        "feed": "open_orders_verbose",
        //        "order": {
        //            "instrument": "PI_XBTUSD",
        //            "time": 1567597581495,
        //            "last_update_time": 1567597581495,
        //            "qty": 102.0,
        //            "filled": 0.0,
        //            "limit_price": 10601.0,
        //            "stop_price": 0.0,
        //            "type": "limit",
        //            "order_id": "fa9806c9-cba9-4661-9f31-8c5fd045a95d",
        //            "direction": 0,
        //            "reduce_only": false
        //        },
        //        "is_cancel": true,
        //        "reason": "post_order_failed_because_it_would_be_filled"
        //    }
        //
        // update
        //
        //    {
        //        "feed": "open_orders",
        //        "order": {
        //          "instrument": "PI_XBTUSD",
        //          "time": 1567702877410,
        //          "last_update_time": 1567702877410,
        //          "qty": 304.0,
        //          "filled": 0.0,
        //          "limit_price": 10640.0,
        //          "stop_price": 0.0,
        //          "type": "limit",
        //          "order_id": "59302619-41d2-4f0b-941f-7e7914760ad3",
        //          "direction": 1,
        //          "reduce_only": true
        //        },
        //        "is_cancel": false,
        //        "reason": "new_placed_order_by_user"
        //    }
        //    {
        //        "feed": "open_orders",
        //        "order_id": "ea8a7144-37db-449b-bb4a-b53c814a0f43",
        //        "is_cancel": true,
        //        "reason": "cancelled_by_user"
        //    }
        //
        //     {
        //         "feed": 'open_orders',
        //         "order": {
        //         "instrument": 'PF_XBTUSD',
        //         "time": 1698159920097,
        //         "last_update_time": 1699835622988,
        //         "qty": 1.1,
        //         "filled": 0,
        //         "limit_price": 20000,
        //         "stop_price": 0,
        //         "type": 'limit',
        //         "order_id": '0eaf02b0-855d-4451-a3b7-e2b3070c1fa4',
        //         "direction": 0,
        //         "reduce_only": false
        //         },
        //         "is_cancel": false,
        //         "reason": 'edited_by_user'
        //     }
        //
        ccxt.pro.ArrayCache orders = this.orders;
        if ((orders == null))
        {
            Int64? limit = this.safeInteger(this.options, "ordersLimit");
            orders = new ArrayCacheBySymbolById(limit);
            this.orders = orders;
        }
        IDictionary<string, object> order = this.safeDict(message, "order");
        if ((order != null))
        {
            string? marketId = this.safeString(order, "instrument");
            string? feed = this.safeString(message, "feed");
            string messageHash = "orders";
            if ((feed == "open_orders_verbose"))
            {
                messageHash = "orders:verbose";
            }
            string? symbol = this.safeSymbol(marketId);
            string? orderId = this.safeString(order, "order_id");
            IDictionary<string, object> previousOrders = this.safeDict((orders as ArrayCache).hashmap, symbol, new Dictionary<string, object>() {});
            IDictionary<string, object> previousOrder = this.safeDict(previousOrders, orderId);
            string? reason = this.safeString(message, "reason");
            if (((previousOrder == null)) || ((reason == "edited_by_user")))
            {
                Dictionary<string, object> parsed = this.parseWsOrder(order);
                orders.append(parsed);
                client.resolve(orders, messageHash);
                client.resolve(orders, ((messageHash + ":") + symbol));
            } else
            {
                Dictionary<string, object> trade = this.parseWsTrade(order);
                if (isEqual(GetValue(previousOrder, "trades"), null))
                {
                    previousOrder["trades"] = new List<object>() {};
                }
                ((IList<object>)GetValue(previousOrder, "trades")).Add(trade);
                previousOrder["lastTradeTimestamp"] = (trade != null && ((IDictionary<string, object>)trade).ContainsKey("timestamp") ? ((IDictionary<string, object>)trade)["timestamp"] : null);
                string? totalCost = "0";
                string? totalAmount = "0";
                object trades = GetValue(previousOrder, "trades");
                for (int i = 0; i < getArrayLength(trades); i++)
                {
                    object currentTrade = getValue(trades, i);
                    totalCost = Precise.stringAdd(totalCost, this.numberToString(getValue(currentTrade, "cost")));
                    totalAmount = Precise.stringAdd(totalAmount, this.numberToString(getValue(currentTrade, "amount")));
                }
                if (Precise.stringGt(totalAmount, "0"))
                {
                    previousOrder["average"] = Precise.stringDiv(totalCost, totalAmount);
                }
                previousOrder["cost"] = totalCost;
                string? filledString = this.numberToString((trade != null && ((IDictionary<string, object>)trade).ContainsKey("amount") ? ((IDictionary<string, object>)trade)["amount"] : null));
                string? stringOrderFilled = this.safeString(previousOrder, "filled", "0");
                string? totalFilled = Precise.stringAdd(stringOrderFilled, filledString);
                previousOrder["filled"] = totalFilled;
                string? prevAmountString = this.safeString(previousOrder, "amount");
                string? remaining = Precise.stringSub(prevAmountString, totalFilled);
                previousOrder["remaining"] = remaining;
                if (isEqual(GetValue(previousOrder, "fee"), null))
                {
                    previousOrder["fee"] = new Dictionary<string, object>() {
                        { "rate", null },
                        { "cost", "0" },
                        { "currency", this.numberToString(this.safeString((trade != null && ((IDictionary<string, object>)trade).ContainsKey("fee") ? ((IDictionary<string, object>)trade)["fee"] : null), "currency")) },
                    };
                }
                if ((!isEqual(getValue(GetValue(previousOrder, "fee"), "cost"), null)) && (!isEqual(this.safeNumber((trade != null && ((IDictionary<string, object>)trade).ContainsKey("fee") ? ((IDictionary<string, object>)trade)["fee"] : null), "cost"), null)))
                {
                    string? stringOrderCost = this.numberToString(getValue(GetValue(previousOrder, "fee"), "cost"));
                    string? stringTradeCost = this.numberToString(this.safeNumber((trade != null && ((IDictionary<string, object>)trade).ContainsKey("fee") ? ((IDictionary<string, object>)trade)["fee"] : null), "cost"));
                    ((IDictionary<string,object>)GetValue(previousOrder, "fee"))["cost"] = Precise.stringAdd(stringOrderCost, stringTradeCost);
                }
                // update the newUpdates count
                orders.append(this.safeOrder(previousOrder));
                client.resolve(orders, ((messageHash + ":") + symbol));
                client.resolve(orders, messageHash);
            }
        } else
        {
            bool? isCancel = this.safeBool(message, "is_cancel");
            if ((isCancel == true))
            {
                // Kraken documents is_cancel as "fully filled, cancelled, or
                // rejected". Derive unified status from `reason` instead of
                // mapping every removal to canceled. Preserve reason on info
                // so consumers can tell a user cancel from liquidation, etc.
                string? reason = this.safeString(message, "reason");
                string status = "canceled";
                if ((reason == "full_fill"))
                {
                    status = "closed";
                }
                string? feed = this.safeString(message, "feed");
                string messageHash = "orders";
                if ((feed == "open_orders_verbose"))
                {
                    messageHash = "orders:verbose";
                }
                // get order without symbol
                for (int i = 0; i < getArrayLength(orders); i++)
                {
                    object currentOrder = getValue(orders, i);
                    if (isEqual(getValue(currentOrder, "id"), (message != null && message.ContainsKey("order_id") ? message["order_id"] : null)))
                    {
                        Dictionary<string, object> info = this.extend(this.safeDict(currentOrder, "info", new Dictionary<string, object>() {}), new Dictionary<string, object>() {
                            { "reason", reason },
                        });
                        ((IList<object>)orders)[Convert.ToInt32(i)] = this.extend(currentOrder, new Dictionary<string, object>() {
                            { "status", status },
                            { "info", info },
                        });
                        client.resolve(orders, messageHash);
                        client.resolve(orders, ((messageHash + ":") + (getValue(currentOrder, "symbol"))));
                        break;
                    }
                }
            }
        }
        return message;
    }

    public virtual void handleOrderSnapshot(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // verbose
        //
        //    {
        //        "feed": "open_orders_verbose_snapshot",
        //        "account": "0f9c23b8-63e2-40e4-9592-6d5aa57c12ba",
        //        "orders": [
        //            {
        //                "instrument": "PI_XBTUSD",
        //                "time": 1567428848005,
        //                "last_update_time": 1567428848005,
        //                "qty": 100.0,
        //                "filled": 0.0,
        //                "limit_price": 8500.0,
        //                "stop_price": 0.0,
        //                "type": "limit",
        //                "order_id": "566942c8-a3b5-4184-a451-622b09493129",
        //                "direction": 0,
        //                "reduce_only": false
        //            },
        //            ...
        //        ]
        //    }
        //
        // regular
        //
        //    {
        //        "feed": "open_orders_snapshot",
        //        "account": "e258dba9-4dd4-4da5-bfef-75beb91c098e",
        //        "orders": [
        //            {
        //                "instrument": "PI_XBTUSD",
        //                "time": 1612275024153,
        //                "last_update_time": 1612275024153,
        //                "qty": 1000,
        //                "filled": 0,
        //                "limit_price": 34900,
        //                "stop_price": 13789,
        //                "type": "stop",
        //                "order_id": "723ba95f-13b7-418b-8fcf-ab7ba6620555",
        //                "direction": 1,
        //                "reduce_only": false,
        //                "triggerSignal": "last"
        //            },
        //            ...
        //        ]
        //    }
        List<object> orders = this.safeList(message, "orders", new List<object>() {});
        Int64? limit = this.safeInteger(this.options, "ordersLimit");
        this.orders = new ArrayCacheBySymbolById(limit);
        string? feed = this.safeString(message, "feed");
        string messageHash = "orders";
        if (feed == "open_orders_verbose_snapshot")
        {
            messageHash = "orders:verbose";
        }
        Dictionary<string, object> symbols = new Dictionary<string, object>() {};
        ccxt.pro.ArrayCache cachedOrders = this.orders;
        for (int i = 0; i < orders.Count; i++)
        {
            object order = orders[i];
            Dictionary<string, object> parsed = this.parseWsOrder(order);
            string? symbol = ((string)(parsed != null && ((IDictionary<string, object>)parsed).ContainsKey("symbol") ? ((IDictionary<string, object>)parsed)["symbol"] : null));
            if ((symbol != null))
            {
                symbols[(string)symbol] = true;
            }
            cachedOrders.append(parsed);
        }
        int length = getArrayLength(this.orders);
        if (length > 0)
        {
            client.resolve(this.orders, messageHash);
            List<object> keys = new List<object>(((IDictionary<string,object>)symbols).Keys);
            for (int i = 0; i < keys.Count; i++)
            {
                string? symbol = ((string)keys[i]);
                string symbolMessageHash = ((messageHash + ":") + symbol);
                client.resolve(this.orders, symbolMessageHash);
            }
        }
    }

    public override Dictionary<string, object> parseWsOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // update
        //
        //    {
        //        "feed": "open_orders_verbose",
        //        "order": {
        //            "instrument": "PI_XBTUSD",
        //            "time": 1567597581495,
        //            "last_update_time": 1567597581495,
        //            "qty": 102.0,
        //            "filled": 0.0,
        //            "limit_price": 10601.0,
        //            "stop_price": 0.0,
        //            "type": "limit",
        //            "order_id": "fa9806c9-cba9-4661-9f31-8c5fd045a95d",
        //            "direction": 0,
        //            "reduce_only": false
        //        },
        //        "is_cancel": true,
        //        "reason": "post_order_failed_because_it_would_be_filled"
        //    }
        //
        // snapshot
        //
        //    {
        //        "instrument": "PI_XBTUSD",
        //        "time": 1567597581495,
        //        "last_update_time": 1567597581495,
        //        "qty": 102.0,
        //        "filled": 0.0,
        //        "limit_price": 10601.0,
        //        "stop_price": 0.0,
        //        "type": "limit",
        //        "order_id": "fa9806c9-cba9-4661-9f31-8c5fd045a95d",
        //        "direction": 0,
        //        "reduce_only": false
        //    }
        //
        bool? isCancelled = this.safeBool(order, "is_cancel");
        object unparsedOrder = order;
        string? status = null;
        if ((isCancelled != null))
        {
            unparsedOrder = this.safeValue(order, "order");
            if ((isCancelled == true))
            {
                status = "cancelled";
            }
        }
        string? marketId = this.safeString(unparsedOrder, "instrument");
        string? timestamp = this.safeString(unparsedOrder, "time");
        Int64? direction = this.safeInteger(unparsedOrder, "direction");
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "symbol", this.safeSymbol(marketId, market) },
            { "id", this.safeString(unparsedOrder, "order_id") },
            { "clientOrderId", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "type", this.safeString(unparsedOrder, "type") },
            { "timeInForce", null },
            { "postOnly", null },
            { "side", ((direction == 0)) ? "buy" : "sell" },
            { "price", this.safeString(unparsedOrder, "limit_price") },
            { "stopPrice", this.safeString(unparsedOrder, "stop_price") },
            { "triggerPrice", this.safeString(unparsedOrder, "stop_price") },
            { "amount", null },
            { "cost", null },
            { "average", null },
            { "filled", this.safeString(unparsedOrder, "filled") },
            { "remaining", this.safeString(unparsedOrder, "qty") },
            { "status", status },
            { "fee", new Dictionary<string, object>() {
                { "rate", null },
                { "cost", null },
                { "currency", null },
            } },
            { "trades", null },
        });
    }

